import afdx as F
TOP = {'lan': ('Mạng cục bộ (LAN) và Ethernet', 'Local area networks (LAN) and Ethernet'), 'afdx': ('AFDX, liên kết ảo và băng thông', 'AFDX, virtual links and bandwidth'), 'frame': ('Khung AFDX và độ tin cậy', 'The AFDX frame and reliability'), 'ima': ('Avionics mô-đun tích hợp (IMA)', 'Integrated modular avionics (IMA)')}
B = Bank(TOP); T = B.T
# ---------------- Tooley Ch.16 (khoa A.16: 1c 2c 3c 4b 5b 6c 7c 8b 9b 10a 11a 12c 13c 14c 15c 16c) ----------------
T(16, 1, 'c', 'lan', 1, 'Trong một mạng Ethernet đơn giản, một máy chủ (host) phát hiện bus đang rảnh hay bận bằng:', 'In a simple ethernet arrangement a host is able to detect whether a bus is idle or busy by means of:', [('kiểm tra chẵn lẻ', 'parity checking'), ('một byte trạng thái', 'a status byte'), ('cảm nhận sóng mang (carrier sense)', 'carrier sense')], 'Đó là chữ CS của CSMA/CD (Tooley 16.4).', 'That is the CS of CSMA/CD (Tooley 16.4).')
T(16, 2, 'c', 'afdx', 1, 'Trong mạng AFDX, các liên kết từ mỗi host tới switch là:', 'In an AFDX network the links from each host to the switch are:', [('đơn công (simplex)', 'simplex'), ('bán song công (half-duplex)', 'half-duplex'), ('song công toàn phần (full-duplex)', 'full-duplex')], 'AFDX là mạng chuyển mạch full-duplex: mỗi liên kết thường gồm hai cặp dây xoắn (Tooley 16.5).', 'AFDX is a switched full-duplex network: each link typically has two twisted pairs (Tooley 16.5).')
T(16, 3, 'c', 'afdx', 1, 'Trong một switch AFDX, bộ đệm (buffer) được dùng cho:', 'Within an AFDX switch a buffer is used:', [('chỉ dữ liệu nhận', 'for received data only'), ('chỉ dữ liệu truyền', 'for transmitted data only'), ('cả dữ liệu nhận và dữ liệu truyền', 'for both received and transmitted data')], 'Mỗi gói nhận được qua bộ đệm trước khi lưu, rồi được chép tới bộ đệm TX (lưu và chuyển tiếp), nên va chạm bị loại bỏ (Tooley 16.5).', 'Each received packet is buffered before storage and then copied to the TX buffer(s) (store and forward), so collisions are eliminated (Tooley 16.5).')
T(16, 4, 'b', 'lan', 2, 'Chiến lược lùi (back-off) của một hệ Ethernet đơn giản dựa trên:', 'The back-off strategy for a simple ethernet system is based on:', [('truyền lại ở các khoảng thời gian đều đặn', 're-transmission at regular time intervals'), ('truyền lại tại một thời điểm ngẫu nhiên trong một khoảng thời gian cho trước', 're-transmission at a random time within a given time interval'), ('truyền lại ngay sau khi phát hiện va chạm', 're-transmission immediately following the detection of a collision')], 'Khoảng ngẫu nhiên gấp đôi sau mỗi lần va chạm: lùi theo hàm mũ nhị phân (Tooley 16.4).', 'The random interval doubles after each collision: binary exponential back-off (Tooley 16.4).')
T(16, 5, 'a', 'afdx', 3, 'BAG lớn nhất cho một VL cung cấp thông điệp với tốc độ 400 thông điệp mỗi giây là:', 'What is the maximum BAG for a VL that supplies messages at a rate of 400 per second:', [('2 ms', '2 ms'), ('4 ms', '4 ms'), ('8 ms', '8 ms')],
  'Tần số tương ứng của BAG phải không nhỏ hơn 400 Hz: BAG 2 ms ứng với 500 Hz, còn 4 ms chỉ 250 Hz (Tooley 16.8, bảng 16.1).', 'The BAG frequency must be at least 400 Hz: a 2 ms BAG is 500 Hz while 4 ms is only 250 Hz (Tooley 16.8, Table 16.1).',
  '<p>Quy tắc của chính Tooley: dữ liệu 100 lần mỗi giây cần BAG không quá 8 ms vì 125 Hz lớn hơn 100 Hz. Áp dụng cho 400 lần mỗi giây: 500 Hz (2 ms) đủ, 250 Hz (4 ms) không đủ. Khoá in ở A.16 là (b); site dùng (a) và ghi vào notes.</p>', '<p>Tooley\'s own rule: data recurring 100 times a second needs a BAG of no more than 8 ms because 125 Hz exceeds 100 Hz. Applied to 400 times a second: 500 Hz (2 ms) is enough, 250 Hz (4 ms) is not. The printed key in A.16 is (b); the site uses (a) and records it in the notes.</p>', printed='b')
T(16, 6, 'c', 'afdx', 3, 'Tốc độ bit lớn nhất mà một liên kết ảo AFDX hỗ trợ khi chiều dài khung lớn nhất là 256 byte và BAG là 128 ms là:', 'What is the maximum bit-rate that can be supported by an AFDX virtual link in which the maximum frame length is 256 bytes and the BAG is 128 ms:', [('4 000 bit/s', '4,000 bits per second'), ('8 000 bit/s', '8,000 bits per second'), ('16 000 bit/s', '16,000 bits per second')], '$256\\times8\\times1000/128=16\\,000$ bit/s.', '$256\\times8\\times1000/128=16{,}000$ bits per second.')
T(16, 7, 'c', 'afdx', 1, 'Khoảng cho phép của BAG trong AFDX là:', 'Allowable bandwidth allocation gaps in AFDX can range from:', [('1 đến 8 ms', '1 to 8 ms'), ('2 đến 64 ms', '2 to 64 ms'), ('1 đến 128 ms', '1 to 128 ms')], 'Bảng 16.1: 1, 2, 4, 8, 16, 32, 64, 128 ms.', 'Table 16.1: 1, 2, 4, 8, 16, 32, 64, 128 ms.')
T(16, 8, 'b', 'afdx', 2, 'Trong mạng AFDX, các khung Ethernet gắn với một VL nhất định có thể bắt nguồn từ:', 'Within an AFDX network, the ethernet frames associated with a particular VL can originate at:', [('nhiều end system', 'multiple end systems'), ('một và chỉ một end system', 'one, and only one, end system'), ('mọi end system có mặt trong mạng', 'each end system present in the network')], 'Khung của một VL phải xuất phát từ đúng một end system (Tooley 16.7).', 'The frame of a VL must originate at one, and only one, end system (Tooley 16.7).')
T(16, 9, 'c', 'frame', 2, 'Trong ngăn xếp giao thức phát, tiêu đề Ethernet được thêm bởi:', 'Within the transmit protocol stack the ethernet header is added by the:', [('lớp truyền tải UDP', 'UDP transport layer'), ('lớp mạng IP', 'IP network layer'), ('lớp liên kết (link layer)', 'link layer')],
  'Thông điệp đi qua UDP, rồi IP, rồi lớp liên kết; lớp liên kết đóng khung Ethernet cuối cùng (Tooley 16.9).', 'The message passes UDP, then IP, then the link layer; the link layer builds the ethernet frame last (Tooley 16.9).',
  '<p>Khoá in A.16 ghi (b); nhưng câu 11 (khoá a) nói thứ tự phát là UDP, IP, lớp liên kết, nên tiêu đề Ethernet chỉ có thể do lớp liên kết thêm vào. Site dùng (c) và ghi vào notes.</p>', '<p>The printed key in A.16 says (b); but question 11 (key a) gives the transmit order UDP, IP, link layer, so the ethernet header can only be added by the link layer. The site uses (c) and records it in the notes.</p>', printed='b')
T(16, 10, 'a', 'frame', 2, 'Trong khung AFDX, FCS xuất hiện:', 'Within the AFDX frame the FCS appears:', [('sau số thứ tự (sequence number)', 'after the sequence number'), ('ngay sau trường thông điệp', 'immediately after the message field'), ('sau địa chỉ IP và trước trường thông điệp', 'after the IP address and before the message field')], 'Thứ tự: payload, đệm nếu cần, SN, rồi FCS cuối khung (Tooley 16.9, Hình 16.7).', 'Order: payload, padding if needed, SN, then the FCS at the end of the frame (Tooley 16.9, Figure 16.7).')
T(16, 11, 'a', 'frame', 2, 'Thứ tự một thông điệp đi qua ngăn xếp giao thức phát của AFDX là:', 'The order in which a message is passed through the AFDX transmit protocol stack is:', [('lớp UDP, lớp IP, lớp liên kết', 'UDP transport layer, IP network layer, link layer'), ('lớp liên kết, lớp IP, lớp UDP', 'link layer, IP network layer, UDP transport layer'), ('lớp IP, lớp UDP, lớp liên kết', 'IP network layer, UDP transport layer, link layer')], 'Nhận là quá trình ngược lại (Tooley 16.9).', 'Reception is the reverse (Tooley 16.9).')
T(16, 12, 'c', 'afdx', 1, 'Kiến trúc mạng cơ bản của mạng AFDX là:', 'The fundamental network architecture used by an AFDX network is:', [('bus', 'bus'), ('cây', 'tree'), ('sao nối tầng (cascaded star)', 'cascaded star')], 'Nhiều hệ avionics nối vào một hoặc nhiều switch trung tâm (Tooley 16.5).', 'Several avionic systems connect to one or more central switches (Tooley 16.5).')
T(16, 13, 'c', 'frame', 1, 'Trong mạng AFDX, độ dài của FCS là:', 'In an AFDX network, the length of the FCS is:', [('một byte', 'one byte'), ('hai byte', 'two bytes'), ('bốn byte', 'four bytes')], 'FCS 4 byte, là CRC tính trên toàn khung (Tooley 16.9).', 'The FCS is 4 bytes, a CRC computed over the whole frame (Tooley 16.9).')
T(16, 14, 'c', 'frame', 2, 'Số thứ tự (SN) của khung AFDX có thể nhận giá trị trong khoảng:', 'An AFDX frame sequence number can take a value between:', [('0 và 15', '0 and 15'), ('1 và 128', '1 and 128'), ('0 và 255', '0 and 255')], 'SN bắt đầu từ 0 khi khởi động, tăng tới 255 rồi quay về 1 (Tooley 16.9).', 'The SN starts at 0 at start-up, increments to 255 and then wraps to 1 (Tooley 16.9).')
T(16, 15, 'c', 'frame', 1, 'Trong mạng AFDX, độ dài tiêu đề UDP là:', 'In an AFDX network the length of the UDP header is:', [('bốn byte', 'four bytes'), ('sáu byte', 'six bytes'), ('tám byte', 'eight bytes')], 'Phần tiêu đề chung 6 + 6 + 2 + 20 + 8 byte (địa chỉ MAC đích, nguồn, Type, IP, UDP) cho khung nhỏ nhất đúng 64 byte.', 'The common header 6 + 6 + 2 + 20 + 8 bytes (MAC destination, source, Type, IP, UDP) gives exactly 64 bytes for the smallest frame.')
T(16, 16, 'c', 'frame', 1, 'Thứ tự các khung liên tiếp mà một end system nhận được có thể kiểm tra bằng:', 'The order of successive frames received by an end system can be checked using:', [('tổng kiểm (checksum)', 'a checksum'), ('kiểm tra chẵn lẻ', 'a parity check'), ('số thứ tự (sequence number)', 'a sequence number')], 'Kiểm tra toàn vẹn dùng SN để bảo đảm khung đến đúng thứ tự (Tooley 16.9).', 'Integrity checking uses the SNs to make sure frames arrive in order (Tooley 16.9).')
# ---------------- Tooley Ch.18 (khoa A.18: 1c 2b 3a 4a 5c 6c 7b 8a 9a 10c) ----------------
T(18, 1, 'c', 'ima', 1, 'Trong máy bay dùng IMA, nhiều chức năng avionics được:', 'In an IMA-based aircraft multiple avionics functions are:', [('thực hiện riêng bằng phần mềm nằm hoàn toàn trong các LRU', 'performed individually by software resident solely within LRU'), ('liên hợp (federated) mà không cần nền tính toán tập trung', 'federated without the need for a centralised computing platform'), ('tách thành ứng dụng phần mềm và các end system, trao đổi qua tài nguyên mạng dùng chung', 'split into software applications and end systems communicating over shared network resources')], 'Đó là kiến trúc phân tán của IMA (Tooley 18.2).', 'That is the distributed architecture of IMA (Tooley 18.2).')
T(18, 2, 'b', 'ima', 2, 'Trong máy bay IMA, các chức năng avionics chuyên dụng như quản lý nhiên liệu và điều khiển động cơ:', 'In an IMA-based aircraft, dedicated avionics functions such as fuel management and engine control:', [('không trao đổi qua tài nguyên mạng dùng chung', 'do not communicate using a shared network resource'), ('có thể lấy từ các nhà cung cấp hệ avionics khác nhau', 'can be obtained from different avionic system suppliers'), ('chỉ có thể do nhà chế tạo máy bay gốc cung cấp', 'can only be supplied by the original aircraft manufacturer')], 'IMA mở hỗ trợ avionics đa nguồn (Tooley 18.2.1).', 'An open IMA supports multiple-source avionics (Tooley 18.2.1).')
T(18, 3, 'a', 'ima', 1, 'Mạng ARINC 664/AFDX dùng trong máy bay IMA, so với hệ avionics liên hợp, mang lại:', 'An ARINC 664/AFDX network is used in an IMA-based aircraft. Compared with a federated avionics system this offers:', [('ít cáp hơn, máy bay nhẹ hơn và chi phí khai thác thấp hơn', 'reduced cabling, reduced aircraft weight and lower operating costs'), ('ít cáp hơn, máy bay nhẹ hơn nhưng chi phí khai thác cao hơn', 'reduced cabling, reduced aircraft weight and higher operating costs'), ('nhiều cáp hơn, máy bay nặng hơn và chi phí cao hơn', 'increased cabling, increased aircraft weight and higher operating costs')], 'Giảm khối lượng cáp giảm nhiên liệu và chi phí khai thác (Tooley 18.1).', 'Less cable weight reduces fuel and operating cost (Tooley 18.1).')
T(18, 4, 'a', 'ima', 2, 'Phần mềm ứng dụng do nhà cung cấp hệ avionics phát triển cho máy bay IMA:', 'The software applications developed by avionic system suppliers for an IMA-based aircraft:', [('phải cho phép đặt (host) trên hệ máy tính của bên thứ ba', 'must permit hosting on a third-party computer system'), ('phải được nạp vào từng LRU riêng', 'must be loaded into individual line replaceable units (LRU)'), ('chỉ được dùng cho các chức năng avionics không quan trọng', 'must only be suitable for use with non-critical avionics functions')], 'Ứng dụng IMA không thuộc lõi hệ điều hành nên có thể kiểm chứng và chứng nhận độc lập (Tooley 18.4).', 'IMA application software is not part of the core operating system and can be validated and certified independently (Tooley 18.4).')
T(18, 5, 'c', 'ima', 2, 'Điều kiện tiên quyết thiết yếu của hệ điều hành thời gian thực (RTOS) dùng trong máy bay IMA là:', 'Which one of the following is an essential prerequisite for the real-time operating system (RTOS) used in an IMA-based aircraft?', [('phải dùng kỹ thuật xử lý theo lô', 'It must use batch processing techniques'), ('phải mã hoá dữ liệu đầu cuối tới đầu cuối', 'It must employ end-to-end data encryption'), ('phải hỗ trợ phân vùng (partitioning) và lập lịch (scheduling)', 'It must support partitioning and scheduling')], 'RTOS quản lý phân vùng bộ nhớ và các lát thời gian (Tooley 18.4).', 'The RTOS manages memory partitions and time slices (Tooley 18.4).')
T(18, 6, 'c', 'ima', 2, 'Trong mạng ARINC 664:', 'In an ARINC 664 network:', [('mọi end system đều phải nối trực tiếp với nền IMA', 'end systems must all be directly connected to the IMA platform'), ('mọi dữ liệu đều đi qua một switch trung tâm trong nền IMA', 'all data is routed through a central switch within the IMA platform'), ('các liên kết ảo (VL) được thiết lập giữa nền IMA và các end system', 'virtual links (VL) are established between the IMA platform and end systems')], 'Các VL là kênh logic dùng chung các liên kết vật lý (Tooley 16.7, 18.3).', 'VLs are logical channels sharing the physical links (Tooley 16.7, 18.3).')
T(18, 7, 'b', 'ima', 1, 'Công nghệ mạng dùng trong máy bay IMA theo ARINC 664 là:', 'Which one of the following describes the network technology found in the IMA-based aircraft using ARINC 664 technology?', [('vòng (ring)', 'Ring'), ('sao nối tầng (cascaded star)', 'Cascaded star'), ('bus mở rộng', 'Extended bus')], 'Tooley 16.5 và 18.3: mạng xương sống chuyển mạch kiểu sao nối tầng.', 'Tooley 16.5 and 18.3: a switched backbone of cascaded star form.')
T(18, 8, 'a', 'ima', 2, 'Trong máy bay IMA, tài nguyên xử lý trung tâm được cấp phát bằng:', 'In an IMA-based aircraft, central processing resources are allocated using:', [('chia lát thời gian (time slicing)', 'time slicing'), ('các switch AFDX', 'AFDX switches'), ('xử lý theo lô', 'batch processing')], 'Mỗi ứng dụng có phân vùng bộ nhớ riêng và lát thời gian riêng (Tooley 18.4).', 'Each application has its own memory partition and time slice (Tooley 18.4).')
T(18, 9, 'a', 'ima', 1, 'Tiêu chuẩn ARINC 653 áp dụng cho:', 'The ARINC 653 standard applies to:', [('các hệ điều hành thời gian thực', 'real-time operating systems'), ('các mạng máy bay tốc độ thấp', 'low-speed aircraft networks'), ('truyền dữ liệu tốc độ cao', 'high-speed data communication')], 'ARINC 653 là chuẩn hàng đầu cho RTOS của IMA (Tooley 18.4).', 'ARINC 653 is the leading standard for IMA RTOS (Tooley 18.4).')
T(18, 10, 'c', 'ima', 1, 'Việc cấp phát tài nguyên trong một RTOS được hỗ trợ bởi:', 'The allocation of resources in a real-time operating system is facilitated by:', [('bộ ánh xạ bộ nhớ', 'a memory mapper'), ('bộ điều khiển I/O nối tiếp', 'a serial I/O controller'), ('bộ điều hành ứng dụng (application executive, APEX)', 'an application executive')], 'APEX cấp phát bộ nhớ và thời gian cho từng ứng dụng (Tooley 18.4).', 'The application executive (APEX) allocates memory and time to each application (Tooley 18.4).')
# ---------------- cau bo sung ----------------
X = B.X
fm = lambda x: f'{x:g}'
for bag in (8, 32, 128, 2):
    hz = F.bag_hz(bag); X('afdx', 1, f'Một BAG {bag} ms tương ứng với tần số (số khung tối đa mỗi giây) là:', f'A BAG of {bag} ms corresponds to a frequency (maximum frames per second) of:', [f'{fm(hz)} Hz', f'{fm(hz * 2)} Hz', f'{fm(hz / 2)} Hz', f'{fm(bag)} Hz'], 0, f'$1000/{bag}={fm(hz)}$ Hz (bảng 16.1).', f'$1000/{bag}={fm(hz)}$ Hz (Table 16.1).', 'BAG và tần số', 'BAG and frequency')
for rate in (100, 30, 200, 60, 10):
    b = F.max_bag(rate); X('afdx', 3, f'Một cổng avionics cung cấp dữ liệu {rate} lần mỗi giây vào một VL. BAG lớn nhất có thể chọn (ms) là:', f'An avionics port supplies data {rate} times a second to a VL. The largest BAG (ms) that can be chosen is:', [str(b), str(b * 2 if b * 2 <= 128 else b // 2), str(max(1, b // 2)), str(b // 4 or 1)], 0,
      f'Cần $1000/\\text{{BAG}}\\ge{rate}$ Hz; trong các giá trị 1, 2, 4, ..., 128 ms, lớn nhất thoả là {b} ms ({fm(1000 / b)} Hz).', f'We need $1000/\\text{{BAG}}\\ge{rate}$ Hz; of 1, 2, 4, ..., 128 ms the largest that works is {b} ms ({fm(1000 / b)} Hz).', 'Chọn BAG', 'Choosing a BAG')
for L, bag in ((1518, 4), (1518, 1), (512, 16), (64, 2), (1000, 20 if False else 8)):
    br = F.bitrate(L, bag); fmt = lambda v: (f'{fm(v / 1e6)} Mbit/s' if v >= 1e6 else f'{fm(v / 1e3)} kbit/s')
    X('afdx', 3, f'Một VL có chiều dài khung lớn nhất {L} byte và BAG {bag} ms. Tốc độ bit lớn nhất của VL là:', f'A VL has a maximum frame length of {L} bytes and a BAG of {bag} ms. The maximum bit rate of the VL is:', [fmt(br), fmt(br / 8), fmt(br * 8), fmt(br * 2)], 0,
      f'$L_{{max}}\\times8\\times1000/\\text{{BAG}}={L}\\times8\\times1000/{bag}$ = {fmt(br)}.', f'$L_{{max}}\\times8\\times1000/\\text{{BAG}}={L}\\times8\\times1000/{bag}$ = {fmt(br)}.', 'Tốc độ bit tối đa của VL', 'Maximum bit rate of a VL')
for pl in (100, 10, 1471, 1):
    n = F.frame_len(pl); pad = max(0, 17 - pl)
    X('frame', 3, f'Một khung AFDX mang {pl} byte dữ liệu (payload). Chiều dài khung (không tính tiền tố và khoảng cách giữa khung) là:', f'An AFDX frame carries {pl} bytes of payload. The frame length (not counting the preamble and the inter-frame gap) is:', [(f'{n} byte', f'{n} bytes'), (f'{n - 4} byte', f'{n - 4} bytes'), (f'{n + 12} byte', f'{n + 12} bytes'), (f'{pl + 6 + 6 + 2} byte', f'{pl + 6 + 6 + 2} bytes')], 0,
      f'6 + 6 + 2 + 20 + 8 + {pl}' + (f' + {pad} (đệm cho đủ 17)' if pad else '') + f' + 1 (SN) + 4 (FCS) = {n} byte.', f'6 + 6 + 2 + 20 + 8 + {pl}' + (f' + {pad} (padding up to 17)' if pad else '') + f' + 1 (SN) + 4 (FCS) = {n} bytes.', 'Chiều dài khung AFDX', 'AFDX frame length')
for nb, rate, nm in ((1518, 10e6, '10 Mbit/s'), (1518, 100e6, '100 Mbit/s'), (64, 100e6, '100 Mbit/s')):
    t = F.tx_time(nb, rate); fmt = lambda v: (f'{fm(round(v * 1e3, 4))} ms' if v >= 1e-3 else f'{fm(round(v * 1e6, 4))} μs')
    X('frame', 2, f'Thời gian truyền một khung {nb} byte trên mạng {nm} (chỉ tính bản thân khung) là:', f'The time to transmit a {nb}-byte frame on a {nm} network (the frame itself only) is:', [fmt(t), fmt(t * 8), fmt(t / 8), fmt(t * 10)], 0, f'${nb}\\times8/({nm.split()[0]}\\times10^6)$ = {fmt(t)}.', f'${nb}\\times8/({nm.split()[0]}\\times10^6)$ = {fmt(t)}.', 'Thời gian truyền khung', 'Frame transmission time')
for rate, nm in ((100e6, '100 Mbit/s'), (10e6, '10 Mbit/s')):
    g = F.ifg(rate); fmt = lambda v: f'{fm(round(v * 1e6, 4))} μs'
    X('frame', 2, f'Khoảng cách giữa khung (inter-frame gap) của AFDX dài 12 byte. Trên mạng {nm} nó kéo dài:', f'The AFDX inter-frame gap is 12 bytes long. On a {nm} network it lasts:', [fmt(g), fmt(g * 8), fmt(g / 8), fmt(g * 12)], 0, f'$12\\times8/({nm.split()[0]}\\times10^6)$ = {fmt(g)}.', f'$12\\times8/({nm.split()[0]}\\times10^6)$ = {fmt(g)}.', 'Khoảng cách giữa khung', 'Inter-frame gap')
X('frame', 2, 'Một end system gửi các khung liên tiếp; khung vừa gửi có số thứ tự 255. Số thứ tự của khung kế tiếp là:', 'An end system sends successive frames; the frame just sent has sequence number 255. The next sequence number is:', ['1', '0', '256', '255'], 0, 'SN tăng tới 255 rồi quay về 1 (không về 0; 0 chỉ dùng khi khởi động hoặc đặt lại).', 'The SN increments to 255 and wraps to 1 (not 0; 0 is only used at start-up or reset).', 'Số thứ tự', 'Sequence number')
X('frame', 3, 'Sau khởi động, số thứ tự các khung 1, 2, 3, ... lần lượt là 0, 1, 2, ... Khung thứ 257 mang số thứ tự:', 'After start-up the sequence numbers of frames 1, 2, 3, ... are 0, 1, 2, ... The 257th frame carries the sequence number:', ['1', '0', '2', '256'], 0, 'Khung thứ 256 có SN 255; khung 257 quay về 1.', 'Frame 256 has SN 255; frame 257 wraps to 1.', 'Số thứ tự', 'Sequence number')
for n in (3, 4, 5):
    X('lan', 2, f'Trong lùi theo hàm mũ nhị phân, khoảng thời gian ngẫu nhiên đầu tiên là T. Sau lần va chạm thứ {n}, khoảng chọn thời điểm truyền lại là:', f'In binary exponential back-off the first random interval is T. After collision number {n} the interval for choosing the retransmission time is:', [f'{F.backoff(n, 1):g}T', f'{n}T', f'{n * n}T', 'T'], 0, f'Gấp đôi sau mỗi lần va chạm: $2^{{{n - 1}}}T={F.backoff(n, 1):g}T$.', f'It doubles with each collision: $2^{{{n - 1}}}T={F.backoff(n, 1):g}T$.', 'Lùi hàm mũ nhị phân', 'Binary exponential back-off')
X('afdx', 2, 'ARINC 664 thay thế ARINC 429 với băng thông gấp khoảng một nghìn lần (theo Tooley 18.5). Nếu ARINC 429 tốc độ cao là 100 kbit/s thì mạng AFDX 100 Mbit/s hơn bao nhiêu lần?', 'ARINC 664 replaces ARINC 429 with about a thousand times the bandwidth (Tooley 18.5). If high-speed ARINC 429 is 100 kbit/s, how many times faster is a 100 Mbit/s AFDX network?', ['1,000', '100', '10', '10,000'], 0, '100 Mbit/s / 100 kbit/s = 1 000.', '100 Mbit/s / 100 kbit/s = 1,000.', 'AFDX so với ARINC 429', 'AFDX versus ARINC 429')
# ---- cau van ban theo Tooley 16.1 den 16.9 va 18.1 den 18.5 ----
X('afdx', 1, 'AFDX là cách triển khai của chuẩn ARINC nào, dựa trên công nghệ nào?', 'AFDX is an implementation of which ARINC standard, based on which technology?', [('ARINC 664, dựa trên Ethernet IEEE 802.3', 'ARINC 664, based on IEEE 802.3 ethernet'), ('ARINC 429, dựa trên IEEE 802.5', 'ARINC 429, based on IEEE 802.5'), ('ARINC 653, dựa trên USB', 'ARINC 653, based on USB')], 0, 'Dùng linh kiện thương mại sẵn có (COTS) để giảm chi phí (Tooley 16.5).', 'It uses commercial off-the-shelf (COTS) parts to cut cost (Tooley 16.5).', 'AFDX là gì', 'What AFDX is')
X('afdx', 1, 'AFDX ban đầu được phát triển cho máy bay nào và hiện cũng được triển khai trên máy bay nào (theo Tooley)?', 'AFDX was originally developed for which aircraft, and is now also introduced on which (according to Tooley)?', [('Airbus A380; Boeing 787 Dreamliner', 'Airbus A380; Boeing 787 Dreamliner'), ('Boeing 747; Airbus A300', 'Boeing 747; Airbus A300'), ('Airbus A320; Boeing 737', 'Airbus A320; Boeing 737')], 0, 'Tooley 16.5.', 'Tooley 16.5.', 'AFDX: ứng dụng', 'AFDX: use')
X('lan', 1, 'CSMA/CD của Ethernet nghĩa là:', 'Ethernet\'s CSMA/CD stands for:', [('cảm nhận sóng mang, đa truy cập, phát hiện va chạm', 'carrier sense, multiple access, collision detection'), ('truyền liên tục, đa kênh, kiểm tra dữ liệu', 'continuous send, multiple channel, check data'), ('kiểm tra chẵn lẻ, đa tầng, phát hiện lỗi', 'check parity, multi-stage, catch defects')], 0, 'CS: biết bus rảnh hay bận; MA: nhiều máy dùng chung bus; CD: phát hiện va chạm (Tooley 16.4).', 'CS: know whether the bus is idle or busy; MA: many hosts share the bus; CD: detect collisions (Tooley 16.4).', 'CSMA/CD', 'CSMA/CD')
X('lan', 1, 'Bốn kiểu cấu trúc (topology) LAN thường gặp là:', 'The four commonly met LAN topologies are:', [('sao, vòng, cây và bus', 'star, ring, tree and bus'), ('sao, lưới, cầu và bus', 'star, mesh, bridge and bus'), ('vòng, ngôi sao, hình cầu và đường thẳng', 'ring, star, sphere and line')], 0, 'Bus thực chất là cây chỉ có một thân và không có nhánh (Tooley 16.3).', 'A bus is effectively a tree with one trunk and no branches (Tooley 16.3).', 'Topology LAN', 'LAN topology')
X('lan', 2, 'Trong cấu trúc hình sao, hai nút muốn liên lạc với nhau thì:', 'In a star topology two nodes that want to communicate:', [('gửi yêu cầu tới phần tử chuyển mạch trung tâm, nơi cấp một đường riêng giữa chúng', 'send a request to the central switching element, which gives them a dedicated path'), ('chờ tới lượt trên một vòng kín', 'wait for their turn on a closed ring'), ('cùng phát lên một cáp chung và tránh va chạm', 'transmit on one shared cable and avoid collisions')], 0, 'Bus, cây dùng môi trường đa truy cập nên tại một thời điểm chỉ một thiết bị phát được (Tooley 16.3).', 'Bus and tree use a multiple-access medium so only one device can transmit at a time (Tooley 16.3).', 'Hình sao', 'Star topology')
X('lan', 1, 'Điều nào sau đây là một yêu cầu của LAN theo Tooley 16.2?', 'Which of the following is a LAN requirement in Tooley 16.2?', [('tốc độ dữ liệu cao (ví dụ 10 đến 100 Mbps) và tầm với vài trăm mét dùng cáp rẻ, nhẹ', 'a high data rate (e.g. 10 to 100 Mbps) and a range of several hundred metres on low-cost, light cabling'), ('chỉ dùng một thiết bị điều khiển trung tâm duy nhất', 'a single central controlling device only'), ('tầm với hàng nghìn km', 'a range of thousands of kilometres')], 0, 'LAN nên ít phụ thuộc vào thành phần tập trung (Tooley 16.2).', 'A LAN should exhibit minimum reliance on centralised components (Tooley 16.2).', 'Yêu cầu LAN', 'LAN requirements')
X('afdx', 2, 'Vì sao Ethernet thương mại thông thường không đủ vững chắc cho hàng không vũ trụ?', 'Why is standard commercial-grade ethernet not robust enough for aerospace?', [('vì không bảo đảm dữ liệu được truyền trong một khoảng thời gian cụ thể (không tất định)', 'because it gives no guarantee that data will be transferred within a particular time interval (it is not deterministic)'), ('vì nó quá nhanh', 'because it is too fast'), ('vì nó không dùng được dây xoắn', 'because it cannot use twisted pair')], 0, 'Mạng an toàn cần biết trước độ trễ lớn nhất (Tooley 16.6). AFDX bổ sung QoS, tính tất định và băng thông dành riêng.', 'A safety-critical network must be predictable in its maximum delay (Tooley 16.6). AFDX adds QoS, determinism and guaranteed dedicated bandwidth.', 'Tính tất định', 'Determinism')
X('afdx', 2, 'Trong AFDX, gói tin được định tuyến theo gì, khác với switch Ethernet thông thường dùng địa chỉ MAC đích?', 'In AFDX packets are routed by what, unlike a conventional ethernet switch that uses the destination MAC address?', [('số nhận dạng liên kết ảo (VL ID) 16 bit', 'a 16-bit virtual link identifier (VL ID)'), ('địa chỉ IP nguồn', 'the source IP address'), ('số thứ tự khung', 'the frame sequence number')], 0, 'VL ID nằm trong hai byte cuối của địa chỉ MAC đích, theo sau trường hằng số 32 bit (Tooley 16.7, 16.9).', 'The VL ID sits in the last two bytes of the destination MAC address, following a 32-bit constant field (Tooley 16.7, 16.9).', 'VL ID', 'VL ID')
X('afdx', 2, 'Điều nào đúng về các liên kết ảo (VL) và băng thông?', 'Which statement about virtual links (VL) and bandwidth is correct?', [('tổng băng thông của các VL không được vượt quá băng thông có sẵn, và truyền hai chiều cần một VL bổ sung', 'the total bandwidth of the VLs cannot exceed the available bandwidth, and two-way communication needs a complementary VL'), ('các VL luôn có băng thông không giới hạn', 'VLs always have unlimited bandwidth'), ('một VL có thể có nhiều end system gửi cùng lúc', 'a VL may have several end systems sending at once')], 0, 'Các sub-VL phụ thuộc VL nhưng không có băng thông bảo đảm (Tooley 16.7).', 'Sub-VLs depend on VLs but have no guaranteed bandwidth (Tooley 16.7).', 'Liên kết ảo', 'Virtual links')
X('frame', 2, 'Tiền tố (preamble) trước khung Ethernet gồm:', 'The preamble in front of an ethernet frame consists of:', [('7 byte gồm các bit 0 và 1 xen kẽ, theo sau là 1 byte SFD', '7 bytes of alternating 0 and 1 bits followed by a 1-byte SFD'), ('một byte toàn số 1', 'a single byte of all 1s'), ('4 byte CRC', 'a 4-byte CRC')], 0, 'Tiền tố cho end system thời gian đồng bộ; SFD báo bắt đầu khung thật (Tooley 16.9).', 'The preamble gives the end systems time to synchronise; the SFD signals the start of the actual frame (Tooley 16.9).', 'Tiền tố khung', 'Frame preamble')
X('frame', 2, 'Trường Type của khung AFDX luôn mang giá trị 0x0800, nghĩa là:', 'The Type field of an AFDX frame always has the value 0x0800, which means:', [('dùng giao thức Internet phiên bản 4 (IPv4)', 'use of Internet Protocol version 4 (IPv4)'), ('khung có độ dài tối đa', 'a maximum-length frame'), ('khung dự phòng mạng B', 'a redundant network B frame')], 0, 'Tooley 16.9.', 'Tooley 16.9.', 'Trường Type', 'Type field')
X('frame', 2, 'Hai mạng AFDX dự phòng song song được gọi là:', 'The two redundant parallel AFDX networks are called:', [('Mạng A (đỏ) và Mạng B (xanh lam)', 'Network A (red) and Network B (blue)'), ('Mạng chính và mạng phụ chỉ dùng khi hỏng', 'the main network and a spare used only after failure'), ('Mạng IN và OUT', 'the IN and OUT networks')], 0, 'Mạng B truyền bản sao chính xác; chỉ cần một luồng dữ liệu hợp lệ nên độ tin cậy tăng (Tooley 16.9).', 'Network B carries an exact replica; only one valid data stream is needed so reliability improves (Tooley 16.9).', 'Dự phòng mạng', 'Network redundancy')
X('frame', 2, 'Quản lý dự phòng (redundancy management) trong AFDX làm gì?', 'What does redundancy management do in AFDX?', [('phát hiện và loại bỏ các khung trùng lặp (bản sao của khung đã nhận)', 'detects and drops replica frames (copies of frames already received)'), ('tăng độ dài khung', 'lengthens the frames'), ('tắt switch khi quá tải', 'switches the switch off when overloaded')], 0, 'Kiểm tra toàn vẹn thì kiểm tra SN theo đúng thứ tự (Tooley 16.9).', 'Integrity checking checks that the SNs are in strict order (Tooley 16.9).', 'Quản lý dự phòng', 'Redundancy management')
X('ima', 1, 'IMA khác avionics liên hợp (federated) ở điểm cốt lõi nào?', 'What is the core difference between IMA and federated avionics?', [('nhiều ứng dụng chạy trên nền tính toán dùng chung thay vì mỗi hệ có máy tính riêng', 'many applications run on a shared computing platform instead of each system having its own computer'), ('IMA không dùng máy tính', 'IMA uses no computers'), ('IMA chỉ dùng cho máy bay quân sự', 'IMA is for military aircraft only')], 0, 'IMA là một khái niệm chứ không phải một bộ công nghệ cụ thể (Tooley 18.1).', 'IMA is a concept, not a specific set of technologies (Tooley 18.1).', 'IMA và liên hợp', 'IMA versus federated')
X('ima', 1, 'Ba yếu tố chính của IMA gồm nền tính toán tích hợp cao, mạng dự phòng kép dùng chung (ARINC 664/AFDX) và:', 'The three key elements of IMA are a high-integrity common computing resource, a shared dual-redundant network (ARINC 664/AFDX) and:', [('kiến trúc phân tán: ứng dụng phần mềm tập trung cùng các end system đặt từ xa', 'a distributed architecture: centrally computed software applications and remotely located end systems'), ('một cáp đồng trục duy nhất', 'a single coaxial cable'), ('một phi công tự động', 'an automatic pilot')], 0, 'Tooley 18.2.', 'Tooley 18.2.', 'Yếu tố của IMA', 'IMA elements')
X('ima', 2, 'Điều nào sau đây có thể được lưu trữ tập trung trên nền IMA?', 'Which of the following can be hosted centrally on an IMA platform?', [('điều hoà không khí, quản lý nhiên liệu, phanh và càng đáp', 'air conditioning, fuel management, brakes and landing gear'), ('chỉ màn hình buồng lái', 'cockpit displays only'), ('chỉ ăng ten GPS', 'GPS antennas only')], 0, 'Còn có bảo vệ băng và mưa, cảm biến tiệm cận, phát hiện cháy (Tooley 18.2).', 'Also ice and rain protection, proximity sensing and fire detection (Tooley 18.2).', 'Chức năng IMA', 'IMA functions')
X('ima', 2, 'IMA mở khác IMA đóng ở chỗ:', 'An open IMA differs from a closed IMA in that it:', [('hỗ trợ avionics từ nhiều nhà cung cấp', 'supports avionics from several suppliers'), ('chỉ dùng một ngôn ngữ lập trình', 'uses only one programming language'), ('không có mạng', 'has no network')], 0, 'A380 là bán mở (một nhà cung cấp tủ phần cứng, hệ điều hành chung); Boeing 777 dùng AIMS của Honeywell nên là hệ đóng (Tooley 18.2.1).', 'The A380 is semi-open (one hardware cabinet supplier, a shared operating system); the Boeing 777 uses Honeywell\'s AIMS so it is closed (Tooley 18.2.1).', 'IMA mở và đóng', 'Open and closed IMA')
X('ima', 2, 'Trên Airbus A380, CPIOM khác IOM ở chỗ:', 'On the Airbus A380 a CPIOM differs from an IOM in that it:', [('CPIOM chứa tài nguyên tính toán lưu trữ ứng dụng avionics; IOM chỉ đổi dữ liệu không-AFDX sang AFDX', 'a CPIOM provides computing resource hosting avionic applications; an IOM only converts non-AFDX data to AFDX'), ('CPIOM chỉ là ăng ten', 'a CPIOM is only an antenna'), ('IOM chạy các ứng dụng quan trọng nhất', 'an IOM runs the most critical applications')], 0, 'Tooley 18.3.1.', 'Tooley 18.3.1.', 'CPIOM và IOM', 'CPIOM and IOM')
X('ima', 2, 'Mỗi ứng dụng avionics trên nền IMA tồn tại trong:', 'Each avionic application on an IMA platform lives in:', [('một phân vùng bộ nhớ riêng (có tường lửa) với lát thời gian riêng', 'its own reserved memory partition (firewalled) with a dedicated time slice'), ('vùng bộ nhớ chung với mọi ứng dụng khác', 'a memory area shared with every other application'), ('một LRU riêng', 'its own LRU')], 0, 'APEX quản lý phân vùng, tiến trình, thời gian và xử lý lỗi; chuẩn là ARINC 653 (Tooley 18.4).', 'The APEX manages partitions, processes, timing and error handling; the standard is ARINC 653 (Tooley 18.4).', 'Phân vùng', 'Partitions')
X('ima', 3, 'Vì sao một số chức năng cực kỳ quan trọng (điều khiển bay, điều khiển động cơ) vẫn có thể nằm trên máy tính avionics chuyên dụng theo kiến trúc liên hợp ngay cả khi có IMA?', 'Why may some critical functions (flight and engine control) stay on dedicated avionics computers in a federated architecture even where IMA exists?', [('vì không phải mọi ứng dụng bắt buộc chuyển lên nền IMA', 'because not every application has to be moved to the IMA platform'), ('vì IMA không dùng được mạng', 'because IMA cannot use a network'), ('vì luật cấm', 'because the law forbids it')], 0, 'Tooley 18.4: xu hướng chuyển dần, nhưng các ứng dụng tới hạn có thể giữ ở máy tính chuyên dụng.', 'Tooley 18.4: the trend is gradual, but critical applications may remain on dedicated computers.', 'IMA và ứng dụng tới hạn', 'IMA and critical applications')
# ---- tu luan ----
B.E('afdx', 3, 'Một VL AFDX có chiều dài khung lớn nhất 1 518 byte. (a) Tốc độ bit lớn nhất với BAG 4 ms. (b) Cổng avionics cung cấp dữ liệu 150 lần mỗi giây: BAG lớn nhất có thể chọn? (c) Với BAG đó tốc độ bit tối đa của VL là bao nhiêu? (d) Thời gian truyền một khung dài nhất trên mạng 100 Mbit/s?',
  'An AFDX VL has a maximum frame length of 1,518 bytes. (a) The maximum bit rate with a BAG of 4 ms. (b) An avionics port supplies data 150 times a second: what is the largest BAG you can choose? (c) What is then the maximum bit rate of the VL? (d) The time to transmit one longest frame on a 100 Mbit/s network?',
  f'(a) $1518\\times8\\times1000/4$ = {F.bitrate(1518, 4):,.0f} bit/s ≈ 3 Mbit/s (Tooley 16.8). (b) Cần ≥ 150 Hz: 125 Hz (8 ms) không đủ, 250 Hz (4 ms) đủ, nên BAG = {F.max_bag(150)} ms. (c) {F.bitrate(1518, F.max_bag(150)):,.0f} bit/s. (d) $1518\\times8/10^8$ = {F.tx_time(1518, 100e6) * 1e6:.2f} μs.',
  f'(a) $1518\\times8\\times1000/4$ = {F.bitrate(1518, 4):,.0f} bit/s ≈ 3 Mbit/s (Tooley 16.8). (b) It must be at least 150 Hz: 125 Hz (8 ms) is not enough, 250 Hz (4 ms) is, so BAG = {F.max_bag(150)} ms. (c) {F.bitrate(1518, F.max_bag(150)):,.0f} bit/s. (d) $1518\\times8/10^8$ = {F.tx_time(1518, 100e6) * 1e6:.2f} μs.', 'Tính toán VL', 'VL calculation')
B.E('frame', 3, 'Kiểm tra số học khung AFDX của Tooley: (a) Tính chiều dài nhỏ nhất và lớn nhất của khung (không kể tiền tố, SFD và khoảng cách giữa khung) từ các trường: MAC đích 6, MAC nguồn 6, Type 2, IP 20, UDP 8, payload 1 đến 1 471, đệm, SN 1, FCS 4. (b) Khi nào cần đệm và tối đa bao nhiêu byte? (c) Thời gian truyền khung lớn nhất trên mạng 10 Mbit/s?',
  'Check the arithmetic of the Tooley AFDX frame: (a) Compute the minimum and maximum frame length (excluding the preamble, SFD and inter-frame gap) from the fields: MAC destination 6, MAC source 6, Type 2, IP 20, UDP 8, payload 1 to 1,471, padding, SN 1, FCS 4. (b) When is padding needed and how many bytes at most? (c) The transmit time of the maximum frame on a 10 Mbit/s network?',
  f'(a) Tối thiểu 6 + 6 + 2 + 20 + 8 + 17 + 1 + 4 = {F.frame_len(1)} byte (payload cộng đệm tối thiểu 17); tối đa 6 + 6 + 2 + 20 + 8 + 1 471 + 1 + 4 = {F.frame_len(1471)} byte. (b) Khi payload dưới 17 byte; tối đa 16 byte đệm (payload 1 byte cần 16 byte đệm). (c) $1518\\times8/(10\\times10^6)$ = {F.tx_time(1518, 10e6) * 1e3:.4f} ms; cộng tiền tố 8 byte và khoảng cách 12 byte thì $(1518+20)\\times8/10^7$ = {F.tx_time(1538, 10e6) * 1e3:.4f} ms.',
  f'(a) Minimum 6 + 6 + 2 + 20 + 8 + 17 + 1 + 4 = {F.frame_len(1)} bytes (payload plus padding of at least 17); maximum 6 + 6 + 2 + 20 + 8 + 1,471 + 1 + 4 = {F.frame_len(1471)} bytes. (b) When the payload is below 17 bytes; at most 16 bytes of padding (a 1-byte payload needs 16). (c) $1518\\times8/(10\\times10^6)$ = {F.tx_time(1518, 10e6) * 1e3:.4f} ms; adding the 8-byte preamble and the 12-byte gap gives $(1518+20)\\times8/10^7$ = {F.tx_time(1538, 10e6) * 1e3:.4f} ms.', 'Số học khung AFDX', 'AFDX frame arithmetic')
B.E('ima', 2, 'So sánh kiến trúc liên hợp (federated) và IMA theo bốn tiêu chí của Tooley (Bảng 18.1): xử lý, liên kết dữ liệu và cáp, phần mềm ứng dụng, nhà cung cấp. Nêu năm lợi ích của IMA.',
  'Compare the federated and IMA architectures on the four criteria of Tooley (Table 18.1): processing, data interconnection and cabling, application software, suppliers. State five benefits of IMA.',
  'Liên hợp: nhiều máy tính nhúng riêng cho từng chức năng; nhiều bus tốc độ thấp và trung bình (ARINC 429, 629); phần mềm nằm trên từng LRU, cách ly vật lý; nguồn cung hạn chế. IMA: xử lý tập trung trên nền dùng chung có phân vùng; mạng xương sống chuyển mạch tốc độ cao (ARINC 664/AFDX); phần mềm cách ly logic; lý tưởng là mã nguồn mở, đa nguồn. Lợi ích: quản lý nhiều chức năng cùng lúc, giảm khối lượng cáp (nhiên liệu, môi trường, chi phí), hỗ trợ chức năng mới (giám sát tình trạng máy bay), hỗ trợ đa nguồn (linh hoạt, phát triển nhanh), giảm phụ tùng và phụ thuộc một nguồn.',
  'Federated: many embedded computers dedicated to separate functions; many low and medium speed buses (ARINC 429, 629); software resident on each LRU, physically firewalled; restricted suppliers. IMA: centralised processing on a shared, partitioned platform; a common high-speed switched backbone (ARINC 664/AFDX); logically firewalled software; ideally open source, multiple sources. Benefits: manage many functions at once, lighter cabling (fuel, environment, cost), support for new functions (aircraft condition monitoring), multi-source support (flexibility, faster development), fewer spares and less single-source dependence.', 'So sánh liên hợp và IMA', 'Federated versus IMA')
